def find_second_smallest(numbers):
    values = []

    for number in numbers:
        if number == 0:
            break
        values.append(number)

    if len(values) < 2:
        return 0

    smallest = min(values)
    second_smallest = None

    for value in values:
        if value != smallest and (second_smallest is None or value < second_smallest):
            second_smallest = value

    return second_smallest if second_smallest is not None else 0
